    html: "﻿<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>随机分组 | EduToolbox · 名单分组<\/title>\n<meta name=\"description\" content=\"根据人数或组数随机分组，支持重新分组、性别平衡、动画演示、全屏展示、本地保存。适合课堂讨论与小组活动。本地处理，隐私安全，离线可用。\">\n<link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E%F0%9F%8E%93%3C/text%3E%3C/svg%3E\">\n<link rel=\"stylesheet\" href=\"random-group.css\">\n<link rel=\"stylesheet\" href=\"../../assets/css/tool-common.css\">\n<\/head>\n<body>\n<div id=\"app\">\n  <!-- 顶栏 -->\n\n  <main class=\"main\">\n    <!-- 左侧：设置面板 -->\n    <section class=\"setup-panel\">\n      <!-- 名单设置 -->\n      <div class=\"block\">\n        <h2 class=\"block-title\">📋 名单列表<\/h2>\n        <p class=\"block-hint\">在此粘贴名单，默认一行一个；可在姓名后加 男/女 以启用性别平衡<\/p>\n        <div class=\"textarea-wrap\">\n          <textarea id=\"names\" placeholder=\"张三&#10;李四 女&#10;王五 男&#10;赵六&#10;...\">张三\n李四 女\n王五 男\n赵六\n钱七 女\n孙八 男\n周九\n吴十 女\n郑十一\n王十二\n刘十三 男\n陈十四\n杨十五 女<\/textarea>\n          <div class=\"textarea-toolbar\">\n            <button class=\"btn-mini\" id=\"exampleBtn\" title=\"加载示例\">示例<\/button>\n            <button class=\"btn-mini\" id=\"clearBtn\" title=\"清空\">清空<\/button>\n          <\/div>\n        <\/div>\n        <div class=\"count-bar\">共 <span id=\"count\">13<\/span> 人<\/div>\n      <\/div>\n\n      <!-- 分组设置 -->\n      <div class=\"block\">\n        <h2 class=\"block-title\">⚙️ 分组设置<\/h2>\n        <div class=\"seg-bar\">\n          <button class=\"seg-btn active\" data-mode=\"group\">按组数分<\/button>\n          <button class=\"seg-btn\" data-mode=\"size\">按每组人数分<\/button>\n        <\/div>\n        <div class=\"setting-row\">\n          <label for=\"num\" id=\"numLabel\">组数<\/label>\n          <div class=\"num-control\">\n            <button class=\"num-btn\" id=\"numMinus\">−<\/button>\n            <input type=\"number\" id=\"num\" min=\"1\" value=\"4\" step=\"1\">\n            <button class=\"num-btn\" id=\"numPlus\">+<\/button>\n          <\/div>\n        <\/div>\n\n        <div class=\"setting-row\">\n          <label for=\"sep\">分隔符<\/label>\n          <select id=\"sep\">\n            <option value=\"auto\">换行符 (自动)<\/option>\n            <option value=\"comma\">逗号 (,)<\/option>\n            <option value=\"space\">空格 ( )<\/option>\n          <\/select>\n        <\/div>\n      <\/div>\n\n      <!-- 选项 -->\n      <div class=\"block\">\n        <h2 class=\"block-title\">🎨 高级选项<\/h2>\n        <label class=\"check-line\">\n          <input type=\"checkbox\" id=\"balance\">\n          <span>性别平衡（男女均匀分配）<\/span>\n        <\/label>\n        <label class=\"check-line\">\n          <input type=\"checkbox\" id=\"animate\" checked>\n          <span>分组动画演示<\/span>\n        <\/label>\n        <label class=\"check-line\">\n          <input type=\"checkbox\" id=\"autoSave\" checked>\n          <span>本地保存名单 (localStorage)<\/span>\n        <\/label>\n      <\/div>\n\n      <!-- 操作按钮 -->\n      <div class=\"actions\">\n        <button class=\"btn-primary\" id=\"genBtn\">🎲 开始分组<\/button>\n        <button class=\"btn-ghost\" id=\"copyBtn\">📋 复制结果<\/button>\n      <\/div>\n    <\/section>\n\n    <!-- 右侧：分组结果 -->\n    <section class=\"stage\" id=\"stage\">\n      <!-- 舞台工具栏：⛶ 全屏 / ⚙ 隐藏设置（交互由共享模块 tool-stage-toolbar.js 提供） -->\n      <div class=\"stage-toolbar\">\n        <button type=\"button\" class=\"icon-btn\" id=\"fullscreenBtn\" title=\"全屏\">⛶<\/button>\n        <button type=\"button\" class=\"icon-btn\" id=\"hideSetupBtn\" title=\"隐藏设置\">⚙<\/button>\n      <\/div>\n      <div class=\"stage-inner\">\n        <h2 class=\"stage-title\">🎯 分组结果<\/h2>\n        <div class=\"result\" id=\"result\">\n          <div class=\"tip\">输入名单并点击\"开始分组\"按钮<\/div>\n        <\/div>\n      <\/div>\n    <\/section>\n  <\/main>\n<\/div>\n\n<script src=\"../../assets/js/frame-bridge.js\"><\/script>\n<script src=\"../../assets/js/tool-stage-toolbar.js\"><\/script>\n<script src=\"random-group.js\"><\/script>\n<\/body>\n<\/html>\n",
